const page=await figma.getNodeByIdAsync('194:38164');await figma.setCurrentPageAsync(page);const created=[],mutated=[],removed=[],manifest=[];const col=await figma.variables.getVariableCollectionByIdAsync('VariableCollectionId:169:2');
for(const id of SOURCES){const s=await figma.getNodeByIdAsync(id),fonts=new Map();for(const t of s.findAll(n=>n.type==='TEXT'))for(const seg of t.getStyledTextSegments(['fontName']))fonts.set(JSON.stringify(seg.fontName),seg.fontName);await Promise.all([...fonts.values()].map(f=>figma.loadFontAsync(f)));
const sid=s.name.slice(0,3),m=s.width===390;let f=page.children.find(n=>n.type==='FRAME'&&n.name.startsWith(sid+' ·')&&n.width===s.width);if(!f){f=figma.createFrame();page.appendChild(f);created.push(f.id);f.x=m?1520:0;f.y=Math.max(...page.children.filter(n=>n!==f).map(n=>n.y+n.height))+160;}else{for(const n of [...f.children]){removed.push(n.id);n.remove();}mutated.push(f.id);}f.name=s.name;f.fills=s.fills;f.resize(s.width,m?844:900);f.clipsContent=true;f.overflowDirection='VERTICAL';
for(const n of s.children){const clone=n.clone();f.appendChild(clone);clone.x=n.x;clone.y=n.y;created.push(clone.id,...('children'in clone?clone.findAll(n=>true).map(n=>n.id):[]));}
const modal=f.children.some(n=>/^(Dialog ·|Suchpalette|Buchung ·)/.test(n.name)),fixed=[];if(!modal){for(const n of f.children){if(n.name==='Globale Werkzeugleiste')fixed.push(n);if(n.name==='Hauptnavigation'){n.y=772;fixed.push(n);mutated.push(n.id);}if(n.name==='Navigation · Planliste'){n.resize(236,900);const b=n.children.find(n=>n.name.includes('Profil /'));if(b){b.y=828;mutated.push(b.id);}fixed.push(n);mutated.push(n.id);}}for(const n of fixed)f.appendChild(n);}f.numberOfFixedChildren=fixed.length;f.setExplicitVariableModeForCollection(col,col.modes.find(mode=>mode.name===(m?'Dunkel':'Hell')).modeId);manifest.push({source:s.id,prototype:f.id,scenario:sid,mobile:m,sourceHeight:s.height,viewport:f.height,fixed:fixed.length});}
return{createdNodeIds:[...new Set(created)],mutatedNodeIds:[...new Set(mutated)],removedNodeIds:removed,manifest};
